#!/usr/bin/env python3
"""Render the independent dense-R retained-input oracle as a portable fixture."""
import json
from pathlib import Path

root = Path(__file__).resolve().parents[3]
packet = root / 'docs/verification/fgls-diagnosis-20261011/analysis'
rows = json.loads((packet / 'oracle-fixtures.json').read_text())
target = root / 'modules/first-level-laws/shared/src/test/scala/scalafim/fmri/laws/FglsKnownOracleFixtures.scala'
lines = ['package scalafim.fmri.laws', '',
         '/** Generated by tools/scenarios/fgls-diagnosis/generate_scala_fixtures.py',
         '  * from independent R dense retained-row covariance GLS. No fresh streams.',
         '  */', 'private[laws] object FglsKnownOracleFixtures:',
         '  final case class Expected(cell: String, voxel: Int, replicate: Int, coefficients: Vector[Double],',
         '      residualVariance: Double, variance: Double, probability: Double, df: Int)',
         '  val values: Vector[Expected] = Vector(']
entries = []
for cell in rows:
    for voxel, fixtures in enumerate(cell['voxels']):
        for f in fixtures:
            coefficients = ', '.join(repr(float(v)) for v in f['coefficients'])
            entries.append('    Expected(' + json.dumps(cell['cell']) + f', {voxel}, {f["replicate"]},\n' +
                f'      Vector({coefficients}),\n' +
                f'      {f["residual_variance"]}, {f["variance"]}, {f["probability"]}, {f["df"]})')
lines += [',\n'.join(entries), '  )', '']
target.write_text('\n'.join(lines))
